32	public abstract class DecimalLogicalTypeProcessor extends JsonFieldProcessor {
33	
34	  /**
35	   * Check if the given schema is a valid decimal type configuration.
36	   */
37	  protected static boolean isValidDecimalTypeConfig(Schema schema) {
38	    LogicalTypes.Decimal decimalType = (LogicalTypes.Decimal) schema.getLogicalType();
39	    // At the time when the schema is found not valid when it is parsed, the Avro Schema.parse will just silently
40	    // set the schema to be null instead of throwing exceptions. Correspondingly, we just check if it is null here.
41	    if (decimalType == null) {
42	      return false;
43	    }
44	    // Even though schema is validated at schema parsing phase, still validate here to be defensive.
45	    decimalType.validate(schema);
46	    return true;
47	  }
48	
49	  /**
50	   * Parse the object to BigDecimal.
51	   *
52	   * @param obj Object to be parsed
53	   * @return Pair object, with left as boolean indicating if the parsing was successful and right as the
54	   * BigDecimal value.
55	   */
56	  protected static Pair<Boolean, BigDecimal> parseObjectToBigDecimal(Object obj, Schema schema) {
57	    BigDecimal bigDecimal = null;
58	    LogicalTypes.Decimal logicalType = (LogicalTypes.Decimal) schema.getLogicalType();
59	    try {
60	      if (obj instanceof BigDecimal) {
61	        bigDecimal = ((BigDecimal) obj).setScale(logicalType.getScale(), RoundingMode.UNNECESSARY);
62	      } else if (obj instanceof String) {
63	        // Case 2: Object is a number in String format.
64	        try {
65	          //encoded big decimal
66	          bigDecimal = HoodieAvroUtils.convertBytesToBigDecimal(decodeStringToBigDecimalBytes(obj),
67	              (LogicalTypes.Decimal) schema.getLogicalType());
68	        } catch (IllegalArgumentException e) {
69	          //no-op
70	        }
71	      }
72	      // None fixed byte or fixed byte conversion failure would end up here.
73	      if (bigDecimal == null) {
74	        bigDecimal = new BigDecimal(obj.toString(), new MathContext(logicalType.getPrecision(), RoundingMode.UNNECESSARY)).setScale(logicalType.getScale(), RoundingMode.UNNECESSARY);
75	      }
76	    } catch (java.lang.NumberFormatException | ArithmeticException ignored) {
77	      /* ignore */
78	    }
79	
80	    if (bigDecimal == null) {
81	      return Pair.of(false, null);
82	    }
83	    // As we don't do rounding, the validation will enforce the scale part and the integer part are all within the
84	    // limit. As a result, if scale is 2 precision is 5, we only allow 3 digits for the integer.
85	    // Allowed: 123.45, 123, 0.12
86	    // Disallowed: 1234 (4 digit integer while the scale has already reserved 2 digit out of the 5 digit precision)
87	    //             123456, 0.12345
88	    LogicalTypes.Decimal decimalType = (LogicalTypes.Decimal) schema.getLogicalType();
89	    if (bigDecimal.scale() > decimalType.getScale()
90	        || (bigDecimal.precision() - bigDecimal.scale()) > (decimalType.getPrecision() - decimalType.getScale())) {
91	      // Correspond to case
92	      // org.apache.avro.AvroTypeException: Cannot encode decimal with scale 5 as scale 2 without rounding.
93	      // org.apache.avro.AvroTypeException: Cannot encode decimal with scale 3 as scale 2 without rounding
94	      return Pair.of(false, null);
95	    }
96	    return Pair.of(true, bigDecimal);
97	  }
98	
99	  protected static byte[] decodeStringToBigDecimalBytes(Object value) {
100	    return Base64.getDecoder().decode(((String) value).getBytes());
101	  }
102	}
